#!/usr/bin/env node
/**
 * Writes look/config.js with LOOK_GOOGLE_CLIENT_ID when present in the environment.
 * Usage: node scripts/inject-google-config.mjs [targetDir]
 */
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const targetDir = path.resolve(process.argv[2] || path.join(__dirname, ".."));
const clientId = (process.env.LOOK_GOOGLE_CLIENT_ID || "").trim();
const out = path.join(targetDir, "config.js");

const body = `/**
 * LOOK public config.
 * Generated by scripts/inject-google-config.mjs — do not hand-edit the Client ID here;
 * set LOOK_GOOGLE_CLIENT_ID and redeploy, or paste under Settings on a device.
 */
export const GOOGLE_CLIENT_ID = ${JSON.stringify(clientId)};
`;

fs.writeFileSync(out, body);
console.log(
  clientId
    ? "Wrote config.js with Google Client ID (" + clientId.slice(0, 12) + "…)"
    : "Wrote config.js with empty Google Client ID (set LOOK_GOOGLE_CLIENT_ID to enable)"
);
